/* Stock. Set soldOut:true on a matcha above when it runs out; every page follows.
   To preview without editing the file: ?soldout=2  or  ?soldout=2,5  (the numbers are the ids). */
(function(){
  var q=/[?&]soldout=([\d,]+)/.exec(location.search); if(!q) return;
  q[1].split(',').forEach(function(id){LIST.forEach(function(p){if(p.id===+id) p.soldOut=true})});
})();

var TY={ u:{en:'Usucha',he:'אוסוצ׳ה',jp:'薄茶'}, k:{en:'Koicha',he:'קוייצ׳ה',jp:'濃茶'} };

/* Pictures of the two premium (koicha) matchas, taken from the packaging files (Premium boxes and cans).
   They plug into the same CSS variables the four older boxes use on every page:
   --b5/--b6 (large, 315x560), --sx-b5/--sx-b6 (search thumbnail), --cx-b5/--cx-b6 (cart thumbnail). */
(function(){
  /* the two stamp masks are embedded: browsers refuse to use a mask image from a separate local file */
  var css=':root{--ps5:url(data:image/webp;base64,);--ps6:url(data:image/webp;base64,);--tin-ik:url(media/products/tin-ikuyo.webp);--tin-as:url(media/products/tin-asahi.webp);';
  LIST.forEach(function(p){
    if(!p.img) return;
    var k=p.n.split(' ')[0].toLowerCase();
    css+='--b'+p.box+':url('+p.img+'box-'+k+'.webp);--sx-b'+p.box+':url('+p.img+'box-'+k+'-sm.webp);--cx-b'+p.box+':url('+p.img+'box-'+k+'-sm.webp);';
  });
  css+='}';
  var s=document.createElement('style'); s.id='nm-cat-vars'; s.textContent=css;
  (document.head||document.documentElement).appendChild(s);
})();

/* The real floor shadow of the box mockups (tools/box-mockups/shadow.py), on the home strip and the shop cards.
   u = usucha cartons, k = the two koicha cartons. Only symmetric insets and background positions here:
   he.js mirrors left/right for Hebrew, and the light in the photos must not flip. */
(function(){
  /* one picture per carton (1-6), so no two shadows are identical; 5 and 6 are the taller koicha cartons */
  var css='.pc .bxs .bx{position:relative}'+
    '.pc .im .bx::after{content:"";position:absolute;inset:0 -60% -20% -60%;pointer-events:none}';
  for(var n=1;n<=6;n++){
    var k=n>4;
    /* home: painted from the picture area of the tile */
    css+='.ff-th:nth-child('+n+') .ff-ta{background:url(media/products/box-shadow-'+n+'-home.webp) no-repeat '+
           (k?'23.89% 114.3% / 156.67% 41%':'26.67% 116.5% / 166.15% 43.44%')+';background-origin:content-box}';
    /* shop cards and sets: a layer around each box (the box itself is punched out of the shadow picture) */
    css+='.pc .im .bx[style*="--b'+n+')"]::after{background:url(media/products/box-shadow-'+n+'.webp) no-repeat '+
           (k?'73.36% 85.35% / 71.21% 34.17%':'78.66% 86.06% / 75.52% 36.2%')+'}';
  }
  /* home tiles are white at rest, the picked one too (its coloured name bar marks it); cream only on hover */
  css+='.ff-band .ff-th,.ff-band .ff-th.on{background:var(--paper)}.ff-band .ff-th:hover{background:var(--paper-muted)}';
  var st=document.createElement('style'); st.id='nm-box-shadow'; st.textContent=css;
  (document.head||document.documentElement).appendChild(st);
})();

/* ---- Taste: the client's four dimensions, and the meter (option C: five cells + a small red stamp for + / ++) ---- */
var DIMS=[
  {k:'umami', jp:'旨甘', en:'Umami and sweetness', he:'אומאמי ומתיקות'},
  {k:'body',  jp:'濃',   en:'Body',                he:'עוצמה / גוף'},
  {k:'bitter',jp:'苦',   en:'Bitterness',          he:'מרירות'},
  {k:'astr',  jp:'渋',   en:'Astringency',         he:'עפיצות'}   /* kanji are our proposal, not the client's */
];
function hasPlus(name){ var p=find(name); if(!p) return false; for(var k in p.scores) if(num(p.scores[k]).plus) return true; return false; }
/* score = '4', '5+', '5++', '0'.  opts.slot = keep room for the stamp (use when the product has any + score), opts.style = extra inline style */
function meter(score,label,opts){
  opts=opts||{}; var n=num(score), c='';
  for(var i=1;i<=5;i++) c+='<i'+(i<=n.v?' class="on"':'')+'></i>';
  var stamp=n.plus?'<span class="nm-hk" aria-hidden="true">'+new Array(n.plus+1).join('+')+'</span>':(opts.slot?'<span></span>':'');
  return '<span class="nm-bar'+(opts.slot?' slot':'')+'"'+(opts.style?' style="'+opts.style+'"':'')+'><span class="nm-m" role="img" aria-label="'+label+' '+score+' of 5">'+c+'</span>'+stamp+'</span>';
}
(function(){
  var s=document.createElement('style'); s.id='nm-taste-css';
  s.textContent='.nm-bar{display:flex;align-items:center;gap:8px;width:100%}.nm-bar.slot{display:grid;grid-template-columns:1fr 32px}'
   +'.nm-m{display:grid;grid-template-columns:repeat(5,1fr);gap:3px;flex:1;min-width:0}'
   +'.nm-m i{height:16px;border:1.5px solid var(--ink,#1a2c27);background:var(--paper,#fffefb)}'
   +'.nm-m i.on{background:var(--pc,var(--ink,#1a2c27));border-color:var(--pc,var(--ink,#1a2c27))}'
   +'.nm-hk{flex:none;width:30px;height:30px;border-radius:999px;border:1.5px solid var(--red,#ce2527);color:var(--red,#ce2527);background:var(--paper,#fffefb);display:grid;place-items:center;font-weight:700;font-size:15px;line-height:1;letter-spacing:-.02em;transform:rotate(-8deg)}';
  (document.head||document.documentElement).appendChild(s);
})();

/* ---- Recipes, as the client wrote them (PDF pages 4-5). Per product: temperature, ratio. Steps depend on usucha / koicha. ---- */
var STEP={
  sift:'Sift the matcha into a dedicated bowl and pour in the hot water.',
  fast:'Whisk with the chasen for about 30 seconds, fast and aggressive, in a W motion.',
  slow:'After 30 seconds, whisk for about another 30 seconds at a slow pace, without making foam.',
  circ:'Whisk with the chasen for about 30 seconds at a medium to fast pace, in a circular motion, without making foam.'
};
var PHOTO='Take a photo of how it turned out?';
function recipe(p){
  var b=p.brew||{}, t=(!b.temp||isTodo(b.temp))?TODO.temp:b.temp+'\u00b0C', u=p.ty==='u';
  return {
    nums: u ? [[t,'water'],[b.usucha||'','usucha, matcha to water'],[b.latte||'','latte, matcha to water']]
            : [[t,'water'],[b.koicha||'','matcha to water'],['~30 s','whisked']],
    steps: u ? [['sieve',STEP.sift],['chasen',STEP.fast],['chasen',STEP.slow]]
             : [['sieve',STEP.sift],['chasen',STEP.circ]],
    photo: PHOTO
  };
}

/* a score as the client wrote it ('5', '5+', '5++', '0') -> {v:5, plus:2} */
function num(s){ s=String(s); var m=/^(\d+)(\+*)$/.exec(s); return m?{v:+m[1],plus:m[2].length}:{v:null,plus:0}; }

function find(name){ for(var i=0;i<LIST.length;i++) if(LIST[i].n===name) return LIST[i]; return null; }

/* what is inside each set (matcha ids). A set is sold out as soon as one of its matchas is. */
var SETS={'Tasting trio':[1,2,3],'Starter ritual set':[1]};
function soldOutIn(name){
  var p=find(name); if(p) return p.soldOut?[p.n]:[];
  return (SETS[name]||[]).map(function(id){return LIST[id-1]}).filter(function(x){return x.soldOut}).map(function(x){return x.n});
}
function isOut(name){ return soldOutIn(name).length>0; }
(function(){
  var s=document.createElement('style'); s.id='nm-so-css';
  s.textContent='.nm-so{display:inline-flex;align-items:center;gap:6px;height:22px;padding:0 8px;border:1.5px solid #ce2527;border-radius:2px;background:#fffefb;color:#ce2527;font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;line-height:1;white-space:nowrap}:lang(he) .nm-so{letter-spacing:0}#sxo .sx-rw.sx-off .sx-th{filter:grayscale(1);opacity:.42}#sxo .sx-rw.sx-off .sx-pr{opacity:.45}';
  (document.head||document.documentElement).appendChild(s);
})();

/* entries for the search overlay (P list) */
function search(){
  return LIST.map(function(p){
    var o={n:p.n,kj:p.kj,tr:TY[p.ty].en+' · '+p.tag,ty:TY[p.ty].en,tj:TY[p.ty].jp,m:1,price:p.price,size:p.size,
           c:p.c,href:'product-matcha-line.html?p='+p.id};
    if(p.box) o.box=p.box;
    return o;
  });
}

/* the matcha cards of the shop (D.m.items) */
function shop(){
  return LIST.map(function(p){
    return {pg:p.id,n:p.n,kj:p.kj,tr:TY[p.ty].en+' · '+p.tag,st:p.st,ty:p.ty,c:p.c,box:p.box,out:!!p.soldOut,price:p.price,size:p.size,bd:p.badge||'',d:p.tag+'.'};
  });
}

/* entries for the cart and the Hebrew labels (CATN). `extra` = the tools and sets each page adds */
function cart(extra){
  var o={};
  LIST.forEach(function(p){
    o[p.n]={kj:p.kj,tr:TY[p.ty].en+' · '+p.tag,trh:TY[p.ty].he+' · '+p.tagh,ty:TY[p.ty].en,tyh:TY[p.ty].he,c:p.c,p:p.price,sz:p.size,out:!!p.soldOut};
    if(p.box) o[p.n].box=p.box;
  });
  for(var k in (extra||{})){ o[k]=extra[k]; o[k].out=isOut(k); }
  return o;
}

/* ---- Sending failed. The developer calls NMCAT.sendFailed(form) when the server does not answer.
   Preview: ?send=fail (contact and wholesale forms, footer), ?nl=fail (newsletter popup). What was typed stays. ---- */
var SENDFAIL=/[?&](send|nl)=fail/.test(location.search);
function sendFailed(form){
  var host=form.classList.contains('f-form')?form.parentNode:form;
  var old=host.querySelector('.nm-fail'); if(old) old.parentNode.removeChild(old);
  var news=form.classList.contains('f-form')||form.classList.contains('nl-f');
  var box=document.createElement('div'); box.className='nm-fail'; box.setAttribute('role','alert');
  box.innerHTML='<b>'+(news?'We couldn\u2019t sign you up':'Your message didn\u2019t send')+'</b>'+
    '<p>Nothing you typed was lost. Check your connection and try again.</p>'+
    '<div><button type="button">Try again</button>'+(news?'':'<a href="mailto:hello@nomimatcha.co.il">Email us instead</a>')+'</div>';
  if(host!==form) host.appendChild(box); else form.insertBefore(box,form.querySelector('.go,.send,.nl-go'));
  box.querySelector('button').addEventListener('click',function(){
    if(box.parentNode) box.parentNode.removeChild(box);
    if(form.requestSubmit) form.requestSubmit(); else form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
  });
  form.addEventListener('input',function(){ if(box.parentNode) box.parentNode.removeChild(box) },{once:true});
}
